-- V49 SaaS foundation reference. Worker performs migration automatically.
CREATE TABLE IF NOT EXISTS companies(id TEXT PRIMARY KEY,company_code TEXT UNIQUE NOT NULL,company_name TEXT NOT NULL,legal_name TEXT DEFAULT '',gst_no TEXT DEFAULT '',pan_no TEXT DEFAULT '',mobile TEXT DEFAULT '',email TEXT DEFAULT '',address TEXT DEFAULT '',invoice_prefix TEXT DEFAULT 'ML',non_gst_prefix TEXT DEFAULT 'JAY',trip_prefix TEXT DEFAULT 'TR',supplier_prefix TEXT DEFAULT 'PML',status TEXT NOT NULL DEFAULT 'ACTIVE',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS saas_plans(id TEXT PRIMARY KEY,plan_name TEXT UNIQUE NOT NULL,monthly_price REAL DEFAULT 0,yearly_price REAL DEFAULT 0,max_users INTEGER DEFAULT 1,max_trips_month INTEGER DEFAULT 100,max_invoices_month INTEGER DEFAULT 100,max_storage_mb INTEGER DEFAULT 100,features_json TEXT DEFAULT '{}',play_product_id_monthly TEXT DEFAULT '',play_product_id_yearly TEXT DEFAULT '',active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER DEFAULT 0,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS company_subscriptions(id TEXT PRIMARY KEY,company_id TEXT UNIQUE NOT NULL,plan_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'TRIAL',source TEXT NOT NULL DEFAULT 'SYSTEM',trial_started_at TEXT DEFAULT '',trial_ends_at TEXT DEFAULT '',current_period_start TEXT DEFAULT '',current_period_end TEXT DEFAULT '',grace_ends_at TEXT DEFAULT '',play_purchase_token TEXT DEFAULT '',play_order_id TEXT DEFAULT '',auto_renewing INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
